function test_maxOnlyPricingBoundsIgnored() public {
    // Setup: Deploy AMMStandardHook with registry
    address[] memory pairs = new address[](1);
    pairs[0] = tokenB;
    uint160[] memory mins = new uint160[](1);
    mins[0] = 0; // No minimum
    uint160[] memory maxs = new uint160[](1);
    maxs[0] = 1000 * 2**96; // Cap at 1000

    // Action: Set max-only bounds
    vm.prank(address(registry));
    hook.registryUpdatePricingBounds(tokenA, pairs, mins, maxs);

    // Check: `0 | (1000*2**96 == 0)` = `0 | false` = 0 -> isSet = false
    // Execute swap at price >> 1000 -> should revert but passes

    // Assert: Swap succeeds despite exceeding max price
    (uint256 amountIn, uint256 amountOut) = amm.singleSwap(order, fee, feeOnTop, hooks, data);
    assert(amountOut > 0); // Should have reverted
}

function test_clobRoundingDriftInsolvency() public {
    // Setup: CLOB with 100+ small orders at prices maximizing rounding
    // sqrtPriceX96 values where mulDivRoundingUp rounds up

    // Action: Execute 100 small fills (1 wei each)
    // Each fill: calculateFixedInput rounds up TWICE
    // Maker gets ceil(ceil(1 * price / Q96) * price / Q96)
    // For specific prices, each fill gives 1 extra wei to maker

    // Assert: After N fills, sum(makerTokenBalance) > handler balance
    uint256 totalCredits = 0;
    for (uint i = 0; i < makers.length; i++) {
        totalCredits += handler.makerTokenBalance(tokenOut, makers[i]);
    }
    uint256 handlerBalance = IERC20(tokenOut).balanceOf(address(handler));
    assert(totalCredits <= handlerBalance); // Fails if insolvent
}

