    // Hook queues fee collection during beforeSwap

    // Action: Execute swap
    // During _executeQueuedHookFeesByHookTransfers:
    //   _setReentrancyFlags(NO_FLAGS) clears SWAP_GUARD_FLAG
    //   _transferHookFeesByHook makes external token transfer
    //   During transfer callback:
    //     _isReentrancyFlagSet(SWAP_GUARD_FLAG) returns false
    //     But ENTERED bit still blocks nonReentrant modifier

    // Assert: Verify re-entry is still blocked despite flag clearing
    // Check: any view functions that read flags return wrong state
    bool swapInProgress = amm.isReentrancyFlagSet(SWAP_GUARD_FLAG);
    assert(swapInProgress == false); // Flag is cleared mid-swap
}

